const D = { energy:.6, scale:1, density:.5, speed:1, hue:34, x:.5, y:.5, doors:.55, style:'concrete', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

// ---- real-time dolly. bay content is keyed on ABSOLUTE index -> never re-phases
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.30 + .34*K.intensity + .30*P.energy) * .62;
const trav = S.z - Math.floor(S.z), base = Math.floor(S.z);

// ---- incommensurate camera drift (motion floor, no audio required)
const dx = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dy = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9);
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.42 + .58*P.energy) * (.55 + .5*K.intensity) + bass*.35;

const vx = cl(P.x,.1,.9)*width  + u*.030*P.energy*dx;
const vy = cl(P.y,.2,.8)*height + u*.020*P.energy*dy;
const f = u*1.0;
const RW = u*.50*P.scale, CH = u*.50*P.scale, FH = u*.42*P.scale;
const NB = Math.round(7 + P.density*8);
const SP = u*.66, ZMIN = SP*.20;
const sty = P.style, H = ((P.hue%360)+360)%360;

// raking light wanders down the corridor on incommensurate rates
const lz = S.z + 3.2 + 2.4*Math.sin(K.t*.113) + 1.2*Math.sin(K.t*.271+1.3) + .7*Math.sin(K.t*.617+2.2);

const PX = (X,Z) => vx + f*X/Z;
const PY = (Y,Z) => vy + f*Y/Z;

// ---- style tone tables ------------------------------------------------------
const paper = (sty==='engraving');
const line  = (sty==='blueprint');
function ground(){
  if (line)     return [212, 62, 20];
  if (paper)    return [40, 10, 86];
  if (sty==='sodium')   return [26, 40, 7];
  if (sty==='clinical') return [162, 8, 78];
  return [H, 7, 10];
}
// surface: face 0=leftwall 1=rightwall 2=ceiling 3=floor
function surf(face, bi, near, lit){
  const tv = fr(bi*3.7 + face*0.31);
  const rake = (face===0 ? .78 : face===1 ? .42 : face===2 ? .30 : .62);
  let v = (.20 + .62*lit*rake + .10*tv) * (.55 + .45*near);
  if (sty==='sodium')   return [26 + tv*8, cl(58 - 26*lit,10,80), cl(4 + 62*v*1.35, 3, 78)];
  if (sty==='clinical') return [162, cl(5 + 7*tv,0,16), cl(56 + 34*v + 8*tv, 30, 93)];
  if (paper)            return [40, 8, cl(93 - 34*(1-v)*1.1, 44, 96)];
  if (line)             return [212, 60, cl(10 + 18*v, 8, 34)];
  return [H, cl(6 + 10*tv,2,20), cl(6 + 74*v, 4, 84)];  // concrete
}
function ink(a){
  if (line)  { stroke(190, 30, 100, a); }
  else if (paper) { stroke(30, 22, 16, a); }
  else if (sty==='sodium') { stroke(30, 55, 40, a*.7); }
  else if (sty==='clinical') { stroke(168, 14, 40, a*.55); }
  else { stroke(H, 8, 88, a*.35); }
}

// ---- ground -----------------------------------------------------------------
const G = ground(); noStroke(); fill(G[0], G[1], G[2], 100); rect(0,0,width,height);

// ---- quad helper in world space --------------------------------------------
function wq(x0,y0,z0, x1,y1,z1, x2,y2,z2, x3,y3,z3){
  quad(PX(x0,z0),PY(y0,z0), PX(x1,z1),PY(y1,z1), PX(x2,z2),PY(y2,z2), PX(x3,z3),PY(y3,z3));
}
// hatch a projected quad (engraving): n lines from edge a->b to edge d->c
function hatch(ax,ay,bx,by,cx2,cy2,dx2,dy2, n, a){
  ink(a);
  for (let i=1;i<=n;i++){ const s=i/(n+1);
    line(ax+(bx-ax)*s, ay+(by-ay)*s, dx2+(cx2-dx2)*s, dy2+(cy2-dy2)*s);
  }
}

// ---- far end wall + its light -----------------------------------------------
const ZF = (NB - trav)*SP;
noStroke();
const endLit = .55 + .45*Math.sin(K.t*.19 + 1.1)*.5 + .2*K.swell;
if (paper)      fill(40, 6, 97, 100);
else if (line)  fill(212, 50, 26, 100);
else            fill(H, sty==='clinical'?6:18, cl(34 + 46*endLit*glow, 12, 92), 100);
wq(-RW,-CH,ZF,  RW,-CH,ZF,  RW,FH,ZF,  -RW,FH,ZF);
if (!paper && !line){
  push(); blendMode(ADD); noStroke();
  for (let i=5;i>=1;i--){ const rr = f*RW/ZF * (i*.42);
    fill(sty==='sodium'?30:H, sty==='clinical'?10:30, 100, 3 + 5*endLit*glow);
    ellipse(vx, vy + f*(FH-CH)*.5/ZF, rr*2.0, rr*1.5);
  }
  pop(); blendMode(BLEND);
}
ink(60); noFill(); strokeWeight(Math.max(1, u*.0016));
if (line||paper) { const w2=f*RW/ZF, h1=f*CH/ZF, h2=f*FH/ZF; rect(vx-w2, vy-h1, w2*2, h1+h2); }

// ---- bays, far -> near ------------------------------------------------------
strokeWeight(Math.max(1, u*.0018));
for (let k = NB-1; k >= 0; k--){
  const zfr = (k+1 - trav)*SP, znr = (k - trav)*SP;
  if (zfr <= ZMIN) continue;
  const zf = Math.max(zfr, ZMIN), zn = Math.max(znr, ZMIN);
  if (zf - zn < 1e-3) continue;
  const bi = base + k;
  const near = cl(1 - k/NB, 0, 1);
  const ph = bi - lz;
  const lit = cl(.16 + .84*Math.exp(-ph*ph*.30), 0, 1) * (.5 + .5*glow);
  const vis = k < 9;

  // four surfaces of the bay
  const faces = [
    [-RW,-CH,zf, -RW,FH,zf, -RW,FH,zn, -RW,-CH,zn, 0],
    [ RW,-CH,zf,  RW,FH,zf,  RW,FH,zn,  RW,-CH,zn, 1],
    [-RW,-CH,zf,  RW,-CH,zf,  RW,-CH,zn, -RW,-CH,zn, 2],
    [-RW, FH,zf,  RW, FH,zf,  RW, FH,zn, -RW, FH,zn, 3]
  ];
  for (let q=0;q<4;q++){
    const F2 = faces[q], face = F2[12];
    const c = surf(face, bi, near, lit);
    if (line){ noFill(); } else { noStroke(); fill(c[0],c[1],c[2],100); }
    if (!line) wq(F2[0],F2[1],F2[2], F2[3],F2[4],F2[5], F2[6],F2[7],F2[8], F2[9],F2[10],F2[11]);
    if (paper && vis && face!==3){
      const dark = cl(1 - (c[2]-44)/52, 0, 1);
      const n = Math.round(1 + 5*dark);
      hatch(PX(F2[0],F2[2]),PY(F2[1],F2[2]), PX(F2[3],F2[5]),PY(F2[4],F2[5]),
            PX(F2[6],F2[8]),PY(F2[7],F2[8]), PX(F2[9],F2[11]),PY(F2[10],F2[11]), n, 34);
    }
  }

  // rib / pilaster frame standing on the near plane of the bay
  const ir = .90, iw = RW*ir, ic = CH*ir, ifl = FH*ir;
  if (!line && !paper){
    const rc = surf(2, bi, near, cl(lit*1.25,0,1));
    noStroke(); fill(rc[0], rc[1], cl(rc[2]*1.28 + 6, 4, 96), 100);
    wq(-RW,-CH,zn,  RW,-CH,zn,  iw,-ic,zn,  -iw,-ic,zn);
    wq(-RW, FH,zn,  RW, FH,zn,  iw,ifl,zn,  -iw,ifl,zn);
    wq(-RW,-CH,zn, -RW, FH,zn, -iw,ifl,zn,  -iw,-ic,zn);
    wq( RW,-CH,zn,  RW, FH,zn,  iw,ifl,zn,   iw,-ic,zn);
  } else {
    ink(line?78:52); noFill();
    const w1=f*RW/zn, h1=f*CH/zn, h2=f*FH/zn;
    rect(vx-w1, vy-h1, w1*2, h1+h2);
    const w2=f*iw/zn, h3=f*ic/zn, h4=f*ifl/zn;
    rect(vx-w2, vy-h3, w2*2, h3+h4);
  }

  // ceiling fixture — a lit panel in this bay
  const alive = fr(bi*5.1+3) > .18;
  if (alive && !paper){
    const zc = (zn+zf)*.5, hw2 = RW*.16, hd = SP*.16;
    const fl = .55 + .45*Math.sin(K.t*.9 + bi*2.1);
    const b2 = cl((sty==='sodium'?52:66) + 34*glow*fl, 10, 96);
    if (line){ ink(90); noFill(); }
    else { noStroke(); fill(sty==='sodium'?32:(sty==='clinical'?58:H), sty==='clinical'?12:26, b2, 100); }
    wq(-hw2,-CH,zc-hd,  hw2,-CH,zc-hd,  hw2,-CH,zc+hd,  -hw2,-CH,zc+hd);
    if (!line && vis){
      push(); blendMode(ADD); noStroke();
      fill(sty==='sodium'?30:H, 34, 100, cl(4 + 9*glow*fl, 0, 22));
      const cy2 = PY(-CH,zc), sw = f*RW*1.4/zc;
      ellipse(vx, cy2, sw, sw*.36);
      pop(); blendMode(BLEND);
    }
  }

  // recessed doorway on one wall (seeded by absolute bay index)
  const dh = fr(bi*7.3+11);
  if (dh < P.doors*.8 && zn > SP*.5){
    const sgn = (fr(bi*2.9+5) < .5) ? -1 : 1;
    const z0 = zn + SP*.22, z1 = zf - SP*.22;
    const dy0 = FH - CH*.02, dy1 = FH - (CH+FH)*.52;
    const openv = fr(bi*11.7) < .40;
    if (line || paper){ ink(line?85:64); noFill();
      beginShape();
      vertex(PX(sgn*RW,z0),PY(dy0,z0)); vertex(PX(sgn*RW,z0),PY(dy1,z0));
      vertex(PX(sgn*RW,z1),PY(dy1,z1)); vertex(PX(sgn*RW,z1),PY(dy0,z1));
      endShape(CLOSE);
    } else {
      noStroke();
      const dcv = openv ? cl(24 + 60*glow*(.4+.6*lit), 6, 92) : 8 + 12*near;
      fill(openv ? (sty==='sodium'?34:H) : H, openv?30:10, dcv, 100);
      wq(sgn*RW,dy0,z0, sgn*RW,dy1,z0, sgn*RW,dy1,z1, sgn*RW,dy0,z1);
      if (openv && vis){
        push(); blendMode(ADD); noStroke();
        fill(sty==='sodium'?30:H, 32, 100, cl(5 + 10*glow, 0, 20));
        wq(sgn*RW,FH,z0, sgn*RW,FH,z1, sgn*RW*.05,FH,z1, sgn*RW*.05,FH,z0);
        pop(); blendMode(BLEND);
      }
    }
  }
}

// ---- floor sheen travelling with the dolly (partial, never a full flash) ----
if (!paper && !line){
  push(); blendMode(ADD); noStroke();
  for (let i=0;i<3;i++){
    const zz = ((S.z*.5 + i*.37) % 1) * SP*5 + SP*.6;
    fill(sty==='sodium'?32:H, 26, 100, 4 + 7*glow);
    wq(-RW,FH,zz, RW,FH,zz, RW,FH,zz+SP*.30, -RW,FH,zz+SP*.30);
  }
  pop(); blendMode(BLEND);
}

// ---- vignette (cached) ------------------------------------------------------
if (!S.vig || S.vk !== width+'x'+height){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  for (let i=0;i<24;i++){ const s=i/24, bw = (1-s)*.075;
    g.fill(0,0,0, 1.1 + 3.4*s*s);
    g.rect(0,0,width, height*bw); g.rect(0,height*(1-bw), width, height*bw);
    g.rect(0,0, width*bw, height); g.rect(width*(1-bw),0, width*bw, height);
  }
  S.vig = g; S.vk = width+'x'+height;
}
image(S.vig,0,0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
